-- Restrictive gates compose with existing ownership policies; they grant no access on their own.
CREATE POLICY strategy_read_permission ON public.content_strategies AS RESTRICTIVE FOR SELECT TO authenticated USING(private.can_editorial(agency_id,'strategy.view'));
CREATE POLICY strategy_create_permission ON public.content_strategies AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(private.can_editorial(agency_id,'strategy.create') AND (client_id IS NULL OR EXISTS(SELECT 1 FROM public.clients c WHERE c.id=content_strategies.client_id AND c.agency_id=content_strategies.agency_id)));
CREATE POLICY strategy_update_permission ON public.content_strategies AS RESTRICTIVE FOR UPDATE TO authenticated USING(private.can_editorial(agency_id,'strategy.edit')) WITH CHECK(private.can_editorial(agency_id,'strategy.edit') AND (client_id IS NULL OR EXISTS(SELECT 1 FROM public.clients c WHERE c.id=content_strategies.client_id AND c.agency_id=content_strategies.agency_id)));
CREATE POLICY strategy_delete_permission ON public.content_strategies AS RESTRICTIVE FOR DELETE TO authenticated USING(private.can_editorial(agency_id,'strategy.edit'));
DO $$DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['editorial_pillars','content_ideas','editorial_items','strategy_versions','strategy_activity'] LOOP
  EXECUTE format('CREATE POLICY strategy_child_read_permission ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING(private.can_editorial(agency_id,''strategy.view'') AND EXISTS(SELECT 1 FROM public.content_strategies s WHERE s.id=%I.strategy_id AND s.agency_id=%I.agency_id))',t,t,t);
  EXECUTE format('CREATE POLICY strategy_child_create_permission ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK((private.can_editorial(agency_id,''strategy.create'') OR private.can_editorial(agency_id,''strategy.edit'') OR private.can_editorial(agency_id,''strategy.manage_editorial'')) AND EXISTS(SELECT 1 FROM public.content_strategies s WHERE s.id=%I.strategy_id AND s.agency_id=%I.agency_id))',t,t,t);
  EXECUTE format('CREATE POLICY strategy_child_update_permission ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING(private.can_editorial(agency_id,''strategy.edit'') OR private.can_editorial(agency_id,''strategy.manage_editorial'')) WITH CHECK((private.can_editorial(agency_id,''strategy.edit'') OR private.can_editorial(agency_id,''strategy.manage_editorial'')) AND EXISTS(SELECT 1 FROM public.content_strategies s WHERE s.id=%I.strategy_id AND s.agency_id=%I.agency_id))',t,t,t);
  EXECUTE format('CREATE POLICY strategy_child_delete_permission ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING(private.can_editorial(agency_id,''strategy.edit'') OR private.can_editorial(agency_id,''strategy.manage_editorial''))',t);
 END LOOP;
END;$$;
